 final int[] RTAF={20,21,22,24,26,28,30,32,34,36,39,42,45,48,52,55,59,63,68,73,78,84,90,96,103,110,118,127,136,146,156,167,179,192,206,221,237,254,272,292,313,335,359,385,412,442,474,508,544,583,625,670,718,769,825,884,947,1020,1090,1170,1250,1340,1440,1540,1650,1770,1890,2030,2180,2330,2500,2680,2870,3080,3300,3540,3790,4060,4350,4670,5000,5360,5740,6160,6600,7070,7580,8120,8710,9330,10000,10720,11490,12310,13200,14140,15160,16250,17410,18660};final float[] GEQF={20,25,31.5f,40,50,63,80,100,125,160,200,250,315,400,500,630,800,1000,1250,1600,2000,2500,3150,4000,5000,6300,8000,10000,12500,16000,20000};final String[] FXN={"Dual GEQ","Stereo GEQ","Dual TruEQ","Stereo TruEQ","Dual DeEsser","Stereo DeEsser","P1A","P1A Dual","PQ5","PQ5 Stereo","Wave Designer","Limiter","Fair Comp","Fair Comp M/S","Fair Comp Dual","Leisure Comp","Leisure Comp Dual","Ultimo Comp","Ultimo Comp Dual","Enhancer Dual","Enhancer","Exciter Dual","Exciter","Stereo Imager","Edison EX1","Sound Maxer","Amp Dual","Amp","Drive Dual","Drive","Phaser","Filter","Pan/Trem","Sub Octaver"};final HashMap<Integer,Float> snapshot=new HashMap<>(),current=new HashMap<>();final ArrayDeque<HashMap<Integer,Float>> undo=new ArrayDeque<>();
