 void buildUi(){ScrollView sc=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(24,24,24,24);root.setBackgroundColor(Color.rgb(8,11,16));sc.addView(root);root.addView(tv("Well Auto Feedback • M32R",24,true));TextView ver=tv("Android v2.4 • REAL FX SYNC • ADJUSTABLE FEEDBACK • INPUT 1–32",13,false);ver.setTextColor(Color.LTGRAY);root.addView(ver);status=tv("READY — NOT CONNECTED",16,true);status.setTextColor(Color.rgb(251,191,36));root.addView(status);ip=new EditText(this);ip.setSingleLine(true);ip.setText("192.168.2.200");ip.setTextColor(Color.WHITE);root.addView(ip,lp());Button connect=btn("CONNECT M32R");root.addView(connect,lp());root.addView(label("RTA SOURCE • MAIN / BUS / INPUT"));target=spin(makeTargets(),1);root.addView(target,lp());root.addView(label("MODE"));operation=spin(new String[]{"FEEDBACK","FLAT EQ"},0);root.addView(operation,lp());root.addView(label("FX RACK • อ่าน Insert/Effect จาก M32R จริง"));LinearLayout row=new LinearLayout(this);fxSlot=spin(new String[]{"FX5","FX6","FX7","FX8"},1);side=spin(new String[]{"A","B"},0);row.addView(fxSlot,new LinearLayout.LayoutParams(0,-2,1));row.addView(side,new LinearLayout.LayoutParams(0,-2,1));root.addView(row,lp());geqState=tv("FX: waiting for connection",15,true);geqState.setTextColor(Color.LTGRAY);root.addView(geqState);root.addView(label("AUTO FEEDBACK CONFIRM DELAY"));delayMs=spin(new String[]{"0 ms","25 ms","50 ms","100 ms","150 ms","250 ms","500 ms","1000 ms"},2);root.addView(delayMs,lp());root.addView(label("CUT EACH TIME"));cutDb=spin(new String[]{"-1 dB","-2 dB","-3 dB","-4 dB","-5 dB","-6 dB"},2);root.addView(cutDb,lp());startStop=btn("▶ START REALTIME");startStop.setEnabled(false);root.addView(startStop,lp());runState=tv("ENGINE: STOPPED",15,true);root.addView(runState);spectrum=new SpectrumView(this);root.addView(spectrum,new LinearLayout.LayoutParams(-1,390));rtaState=tv("RTA: waiting for M32R",13,false);root.addView(rtaState);candidate=tv("Feedback Candidate: —",17,true);root.addView(candidate);Button u=btn("UNDO LAST GEQ CHANGE"),r=btn("RESTORE ORIGINAL GEQ");root.addView(u,lp());root.addView(r,lp());log=tv("READY",13,false);root.addView(log,lp());setContentView(sc);connect.setOnClickListener(v->connectMixer());startStop.setOnClickListener(v->{if(engineRunning)stopEngine();else startEngine();});u.setOnClickListener(v->undoLast());r.setOnClickListener(v->restore());operation.setOnItemSelectedListener(listener(false));target.setOnItemSelectedListener(listener(true));fxSlot.setOnItemSelectedListener(listener(true));side.setOnItemSelectedListener(listener(true));}
 android.widget.AdapterView.OnItemSelectedListener listener(boolean sync){return new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> p,View v,int x,long id){if(engineRunning)stopEngine();if(connected&&sync){requestGeq();configureRta();}}public void onNothingSelected(android.widget.AdapterView<?> p){}};}
 String[] makeTargets(){String[] a=new String[49];a[0]="Main LR";for(int i=1;i<=16;i++)a[i]=String.format(Locale.US,"Bus %02d",i);for(int i=1;i<=32;i++)a[16+i]=String.format(Locale.US,"Input %02d",i);return a;}TextView tv(String s,int z,boolean b){TextView v=new TextView(this);v.setText(s);v.setTextColor(Color.WHITE);v.setTextSize(z);v.setPadding(0,8,0,8);if(b)v.setTypeface(null,1);return v;}TextView label(String s){TextView v=tv(s,12,true);v.setTextColor(Color.rgb(148,163,184));return v;}Button btn(String s){Button b=new Button(this);b.setText(s);return b;}Spinner spin(String[] a,int n){Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,a));s.setSelection(n);return s;}LinearLayout.LayoutParams lp(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,6,0,6);return p;}void ui(String s){runOnUiThread(()->log.setText(s+"\n"+log.getText()));}void toast(String s){runOnUiThread(()->Toast.makeText(this,s,Toast.LENGTH_SHORT).show());}
 int fx(){return 5+fxSlot.getSelectedItemPosition();}int param(int b){return 1+b+(side.getSelectedItemPosition()==0?0:32);}String pa(int p){return String.format(Locale.US,"/fx/%d/par/%02d",fx(),p);}String targetName(){return String.valueOf(target.getSelectedItem());}int source(){String s=targetName();if(s.startsWith("Main"))return 72;if(s.startsWith("Bus"))return 49+Integer.parseInt(s.substring(4));return 1+Integer.parseInt(s.substring(6));}boolean geqOk(){return fxType==0||fxType==2;}String fxName(){return fxType>=0&&fxType<FXN.length?FXN[fxType]:"Unknown type "+fxType;}int confirmMs(){int[] a={0,25,50,100,150,250,500,1000};return a[delayMs.getSelectedItemPosition()];}float cutStep(){return 1f+cutDb.getSelectedItemPosition();}
 void connectMixer(){mixerIp=ip.getText().toString().trim();stopConnection();new Thread(()->{try{socket=new DatagramSocket();socket.setSoTimeout(700);running=true;sendNow("/info");byte[] b=new byte[4096];DatagramPacket p=new DatagramPacket(b,b.length);socket.receive(p);connected=true;runOnUiThread(()->{status.setText("M32R CONNECTED");status.setTextColor(Color.rgb(52,211,153));startStop.setEnabled(true);});requestGeq();configureRtaNow();new Thread(this::rxLoop).start();new Thread(this::keepAlive).start();}catch(Exception e){runOnUiThread(()->status.setText("NO RESPONSE"));stopConnection();}}).start();}
 void startEngine(){if(!connected){toast("CONNECT M32R ก่อน");return;}if(!geqOk()){toast("FX"+fx()+" ตอนนี้คือ "+fxName()+" ไม่ใช่ Dual GEQ");return;}if(snapshot.size()<20){requestGeq();toast("กำลังอ่าน GEQ กรุณารอสักครู่");return;}engineRunning=true;candStart=0;candBand=-1;resetFlatAverage();runOnUiThread(()->{startStop.setText("■ STOP REALTIME");runState.setText("ENGINE: RUNNING • "+targetName()+" • "+confirmMs()+" ms • -"+(int)cutStep()+" dB");});}void stopEngine(){engineRunning=false;candStart=0;candBand=-1;if(startStop!=null)runOnUiThread(()->{startStop.setText("▶ START REALTIME");runState.setText("ENGINE: STOPPED");});}void stopConnection(){stopEngine();running=false;connected=false;if(socket!=null)socket.close();socket=null;}void resetFlatAverage(){Arrays.fill(flatAverage,0);flatFrames=0;}
 synchronized void sendNow(String a,Object...x)throws Exception{if(socket==null)return;byte[] d=osc(a,x);socket.send(new DatagramPacket(d,d.length,InetAddress.getByName(mixerIp),10023));}void send(String a,Object...x){new Thread(()->{try{sendNow(a,x);}catch(Exception e){}}).start();}void configureRta(){send("/-prefs/rta/source",source());send("/-prefs/rta/pos",0);send("/-prefs/rta/det",1);}void configureRtaNow()throws Exception{sendNow("/-prefs/rta/source",source());sendNow("/-prefs/rta/pos",0);sendNow("/-prefs/rta/det",1);}void requestGeq(){snapshot.clear();current.clear();fxType=-1;send("/fx/"+fx()+"/type");for(int i=0;i<31;i++)send(pa(param(i)));runOnUiThread(()->geqState.setText("FX"+fx()+": reading actual rack..."));}
 void keepAlive(){long t=0;while(running){try{long n=System.currentTimeMillis();sendNow("/xremote");if(n-t>2000){configureRtaNow();sendNow("/meters","/meters/15",1);sendNow("/fx/"+fx()+"/type");t=n;}Thread.sleep(500);}catch(Exception e){}}}void rxLoop(){byte[] b=new byte[65535];while(running){try{DatagramPacket p=new DatagramPacket(b,b.length);socket.receive(p);parse(Arrays.copyOf(p.getData(),p.getLength()));}catch(Exception e){}}}
 void parse(byte[] d){try{int[] o={0};String a=readString(d,o),tags=readString(d,o);if(a.equals("/meters/15")&&tags.contains("b")){int n=ByteBuffer.wrap(d,o[0],4).order(ByteOrder.BIG_ENDIAN).getInt();o[0]+=4;if(n>=200&&o[0]+n<=d.length)decode(Arrays.copyOfRange(d,o[0],o[0]+n));return;}if(a.equals("/fx/"+fx()+"/type")&&tags.length()>1&&tags.charAt(1)=='i'){fxType=ByteBuffer.wrap(d,o[0],4).order(ByteOrder.BIG_ENDIAN).getInt();runOnUiThread(()->{geqState.setText("FX"+fx()+" INSERT: "+fxName()+" • Side "+side.getSelectedItem());geqState.setTextColor(geqOk()?Color.rgb(52,211,153):Color.rgb(251,191,36));});return;}String pre="/fx/"+fx()+"/par/";if(a.startsWith(pre)&&tags.length()>1&&tags.charAt(1)=='f'){int p=Integer.parseInt(a.substring(pre.length()));float v=ByteBuffer.wrap(d,o[0],4).order(ByteOrder.BIG_ENDIAN).getFloat();current.put(p,v);if(!snapshot.containsKey(p))snapshot.put(p,v);}}catch(Exception e){}}
 void decode(byte[] b){int off=b.length>=204?4:0;if(b.length-off<200)return;ByteBuffer bb=ByteBuffer.wrap(b,off,200).order(ByteOrder.LITTLE_ENDIAN);for(int i=0;i<100;i++)rta[i]=bb.getShort()/256f;runOnUiThread(()->{spectrum.setData(rta);rtaState.setText("RTA LIVE • "+targetName());});if(engineRunning){if(operation.getSelectedItemPosition()==0)detectFeedback();else processFlatRealtime();}}
 void detectFeedback(){int bi=-1;float best=0;for(int i=18;i<94;i++){if(rta[i]<-48||rta[i]<=rta[i-1]||rta[i]<=rta[i+1])continue;float s=0;int n=0;for(int j=Math.max(0,i-4);j<Math.min(100,i+5);j++)if(Math.abs(j-i)>=2){s+=rta[j];n++;}float ex=rta[i]-s/n;if(ex>best&&ex>6.5f){best=ex;bi=i;}}if(bi<0){candStart=0;candBand=-1;return;}int band=nearestBand(RTAF[bi]),f=(int)GEQF[band];if(band!=candBand){candBand=band;candStart=System.currentTimeMillis();return;}long held=System.currentTimeMillis()-candStart;runOnUiThread(()->candidate.setText("Feedback: "+f+" Hz • "+held+" / "+confirmMs()+" ms"));if(held>=confirmMs()){int p=param(band);float old=current.containsKey(p)?denorm(current.get(p)):0,cut=Math.max(-15,old-cutStep());pushUndo();writeBand(band,cut);ui("CUT "+f+"Hz • -"+(int)cutStep()+" dB • "+targetName());candStart=0;candBand=-1;}}
 void processFlatRealtime(){for(int i=0;i<31;i++){int q=nearestRta(GEQF[i]);float s=0;int n=0;for(int j=Math.max(0,q-3);j<=Math.min(99,q+3);j++){s+=rta[j];n++;}flatAverage[i]=(flatAverage[i]*flatFrames+s/n)/(flatFrames+1f);}flatFrames++;long now=System.currentTimeMillis();if(flatFrames<24||now-lastFlatApply<5000)return;float[] cp=flatAverage.clone();Arrays.sort(cp);float ref=cp[15];HashMap<Integer,Float> before=new HashMap<>(current);boolean changed=false;for(int i=0;i<31;i++){float err=ref-flatAverage[i];if(Math.abs(err)<1)continue;int p=param(i);float old=current.containsKey(p)?denorm(current.get(p)):0,orig=snapshot.containsKey(p)?denorm(snapshot.get(p)):old;float desired=orig+Math.max(-4,Math.min(2,err*.45f));float step=Math.max(-.5f,Math.min(.5f,desired-old));if(Math.abs(step)>=.1f){writeBand(i,old+step);changed=true;}}if(changed)undo.push(before);lastFlatApply=now;resetFlatAverage();}
 int nearestBand(float f){int b=0;double d=99;for(int i=0;i<31;i++){double x=Math.abs(Math.log(GEQF[i]/f));if(x<d){d=x;b=i;}}return b;}int nearestRta(float f){int b=0;double d=99;for(int i=0;i<100;i++){double x=Math.abs(Math.log(RTAF[i]/f));if(x<d){d=x;b=i;}}return b;}void pushUndo(){undo.push(new HashMap<>(current));if(undo.size()>12)undo.removeLast();}void writeBand(int i,float db){float v=norm(db);int p=param(i);current.put(p,v);send(pa(p),v);}float norm(float db){return Math.max(0,Math.min(1,(db+15)/30));}float denorm(float v){return v*30-15;}void undoLast(){if(undo.isEmpty())return;HashMap<Integer,Float> m=undo.pop();for(Map.Entry<Integer,Float> e:m.entrySet())send(pa(e.getKey()),e.getValue());current.clear();current.putAll(m);}void restore(){for(Map.Entry<Integer,Float> e:snapshot.entrySet())send(pa(e.getKey()),e.getValue());current.clear();current.putAll(snapshot);}
 byte[] osc(String addr,Object...args)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream(),pay=new ByteArrayOutputStream();StringBuilder tags=new StringBuilder(",");for(Object x:args){if(x instanceof Integer){tags.append('i');pay.write(ByteBuffer.allocate(4).order(ByteOrder.BIG_ENDIAN).putInt((Integer)x).array());}else if(x instanceof Float){tags.append('f');pay.write(ByteBuffer.allocate(4).order(ByteOrder.BIG_ENDIAN).putFloat((Float)x).array());}else if(x instanceof String){tags.append('s');pay.write(pad((String)x));}}out.write(pad(addr));out.write(pad(tags.toString()));out.write(pay.toByteArray());return out.toByteArray();}byte[] pad(String s)throws Exception{ByteArrayOutputStream o=new ByteArrayOutputStream();o.write(s.getBytes(StandardCharsets.UTF_8));o.write(0);while(o.size()%4!=0)o.write(0);return o.toByteArray();}String readString(byte[] d,int[] o){int i=o[0],e=i;while(e<d.length&&d[e]!=0)e++;String s=new String(d,i,e-i,StandardCharsets.UTF_8);o[0]=(e+4)&~3;return s;}@Override protected void onDestroy(){stopConnection();super.onDestroy();}
 public static class SpectrumView extends View{Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);float[] data=new float[100];public SpectrumView(android.content.Context c){super(c);Arrays.fill(data,-90);}void setData(float[] d){data=d.clone();invalidate();}@Override protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();p.setColor(Color.rgb(32,45,60));for(int i=1;i<10;i++)c.drawLine(0,h*i/10,w,h*i/10,p);p.setColor(Color.rgb(56,189,248));p.setStrokeWidth(3);Path q=new Path();for(int i=0;i<100;i++){float x=w*i/99,y=(-Math.max(-90,Math.min(0,data[i]))/90)*(h-12)+6;if(i==0)q.moveTo(x,y);else q.lineTo(x,y);}c.drawPath(q,p);}}
